//! The Bonferroni-Holm and Sidak-Holm means comparisons of the one-way ANOVA against numbers from Origin.
//!
//! Reference scripts in `tools/origin-ref/stats4/` (Origin's statistics library, one-way means comparison);
//! the inputs and Origin's numbers are in `fixtures/stats4_origin.rs`, made by `make-fixture1.py`. All inputs
//! were generated by us.
//!
//! Tolerances: the mean differences and standard errors agree to 1e-9; Origin's t tail is off by up to 2e-5
//! relative, so the p-values (and with them the statistic ordering) are compared with 2e-5. The thresholds are
//! closed formulas and agree to 1e-9.

#[path = "fixtures/stats4_origin.rs"]
mod fixtures;

use fixtures::*;
use sheaf_calc::*;

fn near(name: &str, what: &str, got: f64, want: f64, rel: f64) {
    if want.is_nan() {
        assert!(got.is_nan(), "{name}: {what}: got {got:?}, Origin shows nothing");
        return;
    }
    assert!((got - want).abs() <= rel * want.abs() + 1e-12, "{name}: {what}: got {got:?}, Origin gave {want:?}");
}

#[test]
fn holm_comparisons_match_origin() {
    assert!(HOLM.len() >= 40);
    for c in HOLM {
        let method = if c.method == 7 { MeansComparison::HolmBonferroni } else { MeansComparison::HolmSidak };
        let groups: Vec<&[f64]> = c.groups.to_vec();
        let a = anova_one_way(&groups).unwrap();
        let got = a.compare(method, c.alpha);
        assert_eq!(got.len(), c.rows.len(), "{}", c.name);
        for (g, w) in got.iter().zip(c.rows) {
            let name = format!("{} method {} pair {}", c.name, c.method, w.pair);
            // Origin's pair number counts (1,2), (1,3), (2,3), (1,4), ... from 0. Pairs with equal p-values may
            // come in another order than Origin's; the thresholds and verdicts belong to the rank, the pair's own
            // numbers are looked up by the pair.
            let pair_of = |x: &Comparison| x.j * (x.j - 1) / 2 + x.i;
            let own = got.iter().find(|x| pair_of(x) == w.pair).unwrap();
            if pair_of(g) != w.pair {
                assert!((g.p - w.p).abs() <= 2e-5 * w.p, "{name}: order differs and p-values are not tied");
            }
            near(&name, "diff", own.diff, w.diff, 1e-9);
            near(&name, "se", own.se, w.se, 1e-9);
            near(&name, "stat", own.stat, w.stat, 2e-5);
            near(&name, "p", own.p, w.p, 2e-5);
            near(&name, "alpha", g.alpha, w.alpha, 1e-9);
            assert_eq!(g.significant, w.sig, "{name}: significant");
            assert!(g.lcl.is_nan() && g.ucl.is_nan(), "{name}: Holm methods have no interval");
        }
    }
}

#[test]
fn holm_step_down_stops_at_the_first_failure() {
    // The cases `stepdown*` were found by a search: the second smallest p-value is below its own threshold but
    // the smallest is not, and Origin says "not significant" for both.
    let c = HOLM.iter().find(|c| c.name == "stepdown0" && c.method == 7).unwrap();
    assert!(c.rows[1].p < c.rows[1].alpha && !c.rows[1].sig);
}
